import json, sys, glob, collections, re
S = sys.argv[1]
for case in ("P08", "P11", "P02"):
    bo = collections.Counter(); sent = collections.Counter(); ex = {}
    for p in glob.glob(f"{S}/rep/{case}-*.json"):
        d = json.load(open(p))
        if isinstance(d["_bo"], list):
            for n in d["_bo"]:
                t = re.sub(r"[\d.,]+\d", "#", n["text"]); bo[(n["from"], t)] += 1
        for e in d["result"]["trace"]:
            if e["actor"] != "buyer" and e["round"] > 0:
                for s in re.split(r"(?<=[.!?])\s+|\n+", e["move"]["text"]):
                    s2 = re.sub(r"[\d.,]+\d", "#", s.strip())
                    if len(s2) > 25: sent[s2] += 1
    print("=====", case, "BACK OFFICE")
    for (f, t), n in bo.most_common(40): print(f"  {n:3d} [{f}] {t[:230]}")
    print("----- supplier sentences")
    for t, n in sent.most_common(45): print(f"  {n:3d} {t[:260]}")
EOF
uv run python $S/bo.py $S

